const booking = $input.first().json[0];
if (!booking) {
  return [];
}

const html = `
  <div style="font-family:Georgia,serif;max-width:520px;margin:0 auto;padding:32px;background:#fdfaf4;border:1px solid #e4d9c4;">
    <h1 style="color:#8a6a1f;font-weight:normal;">Victorias Luxury SPA &amp; WELLNESS</h1>
    <p>Hi ${booking.guest_name},</p>
    <p>Your deposit has been received and your booking is confirmed. Here are your details:</p>
    <table style="width:100%;margin:16px 0;">
      <tr><td style="padding:6px 0;color:#8a6a1f;">Treatment</td><td style="text-align:right;">${booking.service_name}</td></tr>
      <tr><td style="padding:6px 0;color:#8a6a1f;">Date &amp; Time</td><td style="text-align:right;">${booking.booking_date} at ${booking.booking_time}</td></tr>
      <tr><td style="padding:6px 0;color:#8a6a1f;">Deposit Paid</td><td style="text-align:right;">R${booking.deposit_amount}</td></tr>
    </table>
    <p>Please arrive 10 minutes early. If you need to cancel or reschedule, please give us at least 24 hours' notice.</p>
    <p style="margin-top:24px;">We look forward to welcoming you.</p>
    <p>— Victorias Luxury SPA &amp; WELLNESS, Camps Bay</p>
  </div>
`;

return [{
  json: {
    guest_email: booking.guest_email,
    guest_name: booking.guest_name,
    htmlContent: html
  }
}];
